parameters.jsCode:
// 1. Modificamos el nombre del archivo binario usando .first()
$('Convert Email Body to File').first().binary.data.fileName = 'emailBody.txt';

// 2. Retornamos el elemento usando la sintaxis nativa y segura de n8n
return $('Convert Email Body to File').first();

const inputData = $input.first().json;
const score = inputData.score;
const genes = inputData.genes_implicados || [];

// FIX: gen es {caracteristica, peso} — se accede a gen.caracteristica
const formatoEvidencia = genes.map(gen => `- Indicador activado: ${gen.caracteristica}`).join('\n');

return [{
  json: {
    output:{
    "resumen": "Alerta perimetral automática: El correo electrónico ha sido interceptado y clasificado directamente como amenaza debido a un índice de riesgo crítico.",
    "analisis_tecnico": `Análisis algorítmico completado. El correo electrónico arrojó un score acumulado de ${score}/100, superando el umbral de seguridad tolerado (75/100).`,
    "es_phishing": true,
    "indicadores_phishing": genes,
    "nivel_severidad": score >= 90 ? "Crítico" : "Alto",
    "justificacion_veredicto": `Bloqueo automatizado preventivo por el pipeline del SOC.\n\nLa optimización polinomial basada en Algoritmos Genéticos determinó que la concurrencia de los siguientes factores representa un peligro inminente de fraude o fuga de credenciales:\n\n${formatoEvidencia}\n\nEl mensaje ha sido desviado de la bandeja del usuario de forma inmediata como medida de mitigación.`
  }}
}];

const inputData = $input.first().json;
const score = inputData.score;

return [{
  json: {
    output:{
    "resumen": "Tráfico seguro confirmado: Notificación automatizada del sistema que clasifica el correo electrónico como mensaje legítimo.",
    "analisis_tecnico": `Evaluación inicial satisfactoria. El score de riesgo obtenido es de ${score}/100, manteniéndose por debajo del umbral de sospecha (30/100).`,
    "es_phishing": false,
    "indicadores_phishing": [],
    "nivel_severidad": "Bajo",
    "justificacion_veredicto": "El mensaje superó exitosamente los controles de filtrado perimetral del Algoritmo Genético. No se observaron patrones de ingeniería social, ni anomalías críticas en las firmas de autenticación técnica analizadas en las cabeceras. Se autoriza su entrega ordinaria al usuario."
  }}
}];
